/opt/modules/modulefiles/devtools/libxc/.text:
#%Module1.0
# Determin CPU SIMD
set cpu_flags [exec lscpu | grep "avx"]
if {[regexp "avx512_vnni" $cpu_flags]} {
    set avx_flag avx512
    system echo "AVX512 detected, utilizing the corresponding version..."
} elseif {[regexp "avx2" $cpu_flags]} {
    set avx_flag avx2
    system echo "No AVX512, but AVX2 detected, utilizing the corresponding version..."
} else {
    system echo "CAN NOT determin CPU SIMD, please contact the HPC Admin for help, Nya~~"
}

set libxc_ver "7.0.0"

module-whatis "LIBXC $libxc_ver optimized for Zen5, by yulintao@westlake.edu.cn, CPU SIMD - $avx_flag"

set libxc_home /opt/devtools/libxc/libxc-${libxc_ver}-${avx_flag}
setenv  LIBXC_ROOT  $libxc_home

prepend-path LD_LIBRARY_PATH    $libxc_home/lib
prepend-path LD_RUN_PATH        $libxc_home/lib
prepend-path LIBRARY_PATH       $libxc_home/lib
prepend-path PKG_CONFIG_PATH    $libxc_home/lib/pkgconfig
prepend-path CMAKE_PREFIX_PATH  $libxc_home
prepend-path CPATH              $libxc_home/include
prepend-path C_INCLUDE_PATH              $libxc_home/include
